import {mountShell} from '../shared/shell.js?v=0.18.0';
import {escapeHtml as esc,readStore,writeStore,downloadText} from '../shared/utils.js?v=0.18.0';
import {MODEL,POLICIES,createRun,publicView,preview,projection,advance,policyDecision,commitments,envelope,result,serialize,restore,hour} from './engine.js?v=0.18.0';
import {diagnose,promiseLabel,informationName,preparationRule,matchedComparison} from './study.js?v=0.18.0';
import {renderInformation,renderInspector,renderProbeResults,renderMatched,outputName} from './study-ui.js?v=0.18.0';
import {registerFlexibilityTools} from './webmcp.js?v=0.18.0';
mountShell({active:'flexibility',label:'MODEL 04',title:'Where flexibility gets trapped'});
const STORE='thinking-lab:flexibility:v1';
let probe={kind:'dispatch',dispatchMW:3,liftedIds:[]},inspectorOpen=false;
function resetProbe(){probe={kind:'dispatch',dispatchMW:3,liftedIds:[]};inspectorOpen=false;}
const app=document.querySelector('#app');
const money=(n,sign=false)=>`${n<-.005?'−':sign&&n>.005?'+':''}£${Math.abs(n).toLocaleString('en-GB',{maximumFractionDigits:0})}`;
const dec=(n,d=1)=>Number(n).toFixed(d);
const clamp=(x,a,b)=>Math.min(b,Math.max(a,x));
let state=createRun(14),mode='manual',informed=false,selected=[],dispatch=0,saved=[],runId=String(Date.now()),storageOK=true,error='';
try{const data=readStore(STORE,null);if(data?.current){state=restore(data.current);mode=['manual','firm','open'].includes(data.mode)?data.mode:'manual';informed=!!data.informed;runId=String(data.runId||Date.now());saved=(data.saved||[]).slice(-18).filter(x=>['manual','firm','open'].includes(x.mode)).map(x=>({...x,state:restore(x.data)})).filter(x=>x.state.slot===MODEL.slots);selected=Array.isArray(data.selected)?data.selected:[];dispatch=Number(data.dispatch)||0;let p=preview(publicView(state),selected);if(!p.feasible){selected=[];p=preview(publicView(state));}dispatch=clamp(dispatch,p.range.min,p.range.max);}}catch{state=createRun(14);mode='manual';selected=[];dispatch=0;saved=[];}
function name(entry={mode,informed}){return entry.mode==='manual'?(entry.informed?'Your informed replay':'Your first run'):POLICIES[entry.mode].name;}
function persist(){storageOK=writeStore(STORE,{current:serialize(state),mode,informed,runId,selected,dispatch,saved:saved.map(({state:s,...x})=>({...x,data:serialize(s)}))});}
function say(text){document.querySelector('#announcement').textContent=text;}
function chooseDefaults(){selected=[];const view=publicView(state);if(view.done){dispatch=0;return;}if(mode!=='manual'){const d=policyDecision(view,mode);selected=d.acceptedIds;dispatch=d.dispatchMW;}else{const r=preview(view).range;dispatch=clamp(0,r.min,r.max);}}
if(mode!=='manual'&&state.slot<MODEL.slots)chooseDefaults();
function recordCompleted(){if(state.slot===MODEL.slots&&!saved.some(x=>x.id===runId)){saved.push({id:runId,mode,informed,state});saved=saved.slice(-18);}}
recordCompleted();
function priceText(view,t){return t<view.observedPrices.length?`${money(view.observedPrices[t])}/MWh`:'not revealed';}
function renderOffers(view){
  if(!view.currentOffers.length)return '<div class="no-offer">No new offers. Use the remaining hour and settle your promises.</div>';
  return view.currentOffers.map(o=>{const chosen=selected.includes(o.id);const candidate=chosen?selected.filter(id=>id!==o.id):[...selected,o.id];const allowed=preview(view,candidate).feasible;return `<article class="offer ${chosen?'chosen':''}"><div class="offer-copy"><span class="pill ${o.kind}">${o.kind==='reserve'?'Keep capacity ready':'Promise an export'}</span><h3>${o.title} · ${hour(o.slot)}–${hour(o.slot+1)}</h3><p class="offer-detail">${dec(o.mw)} MW ${o.kind==='delivery'?`for 1 hour · ${money(o.rate)}/MWh`:`for 1 hour · stock held back`}</p></div><div class="offer-response"><div class="offer-pay">${money(o.fee)}</div><button class="button small ${chosen?'primary':''}" data-offer="${o.id}" aria-pressed="${chosen}" ${mode!=='manual'||!allowed?'disabled':''}>${mode!=='manual'?(chosen?'Policy accepts':'Policy declines'):(chosen?'Selected ✓':'Accept offer')}</button></div>${!allowed?'<p class="offer-note">Unavailable: it would leave no feasible way to honour all promises.</p>':''}<button class="button ghost small inspect-offer" data-inspect-offer="${o.id}">${!allowed?'Why is this blocked?':'Explore its constraints'}</button></article>`;}).join('');
}
function constraintText(p){const lines=[];if(p.range.deliveryMW)lines.push(`At least ${dec(p.range.deliveryMW)} MW must go to an energy contract this hour.`);if(p.range.reserveMW)lines.push(`${dec(p.range.reserveMW)} MW and ${dec(p.range.reserveMW/MODEL.dischargeEfficiency,2)} MWh stay available for reserve.`);if(p.range.minEnd>p.range.reserveMW/MODEL.dischargeEfficiency+.01)lines.push(`Finish with at least ${dec(p.range.minEnd,2)} MWh to keep future promises feasible.`);return lines.join(' ');}
function renderDecision(view,p){return `<section class="decision" aria-labelledby="decision-title"><div class="hour-head"><div><span class="small-label">Hour ${view.slot+1} of 6</span><h2 id="decision-title">${hour(view.slot)}–${hour(view.slot+1)}</h2></div><div class="price"><strong>${money(view.currentPrice)}</strong><span>spot price / MWh</span></div></div><div class="decision-body">${error?`<p class="error" role="alert">${esc(error)}</p>`:''}${mode!=='manual'?`<div class="baseline-note"><strong>Replaying: ${POLICIES[mode].name}</strong><br>${POLICIES[mode].description} ${view.conditions.priceNotice?preparationRule:"This policy only sees the current hour and existing promises."}</div>`:''}<h3 class="section-label"><span class="step-number">1</span>Make promises, or keep the space</h3><p class="hint">${view.slot===0?'Select an offer to preview its cost in flexibility. Advance to make it firm.':'New offers expire when you advance. Earlier promises are already firm.'}</p><div class="offer-list">${renderOffers(view)}</div><h3 class="section-label"><span class="step-number">2</span>Use this hour</h3><div class="dispatch-readout"><output id="dispatch-output" for="dispatch-slider"></output><span id="dispatch-kind"></span></div><label class="slider-label" for="dispatch-slider">Battery output (MW; negative imports)</label><input class="dispatch-slider" id="dispatch-slider" type="range" min="${p.range.min}" max="${p.range.max}" step="any" value="${dispatch}" ${mode!=='manual'||p.range.max-p.range.min<.00001?'disabled':''}><div class="range-labels"><span>${dec(p.range.min,2)} MW</span><span>${dec(p.range.max,2)} MW</span></div><div class="dispatch-buttons"><button class="button small" data-dispatch="charge" ${mode!=='manual'||p.range.min>=0?'disabled':''}>Charge max</button><button class="button small" data-dispatch="hold" ${mode!=='manual'?'disabled':''}>${p.range.min>0?'Serve promise':'Hold'}</button><button class="button small" data-dispatch="export" ${mode!=='manual'||p.range.max<=0?'disabled':''}>Export max</button></div>${constraintText(p)?`<p class="constraint">${constraintText(p)}</p>`:''}${renderInspector(view,selected,probe,inspectorOpen)}<div class="settle-row"><div class="action-result"><div><span>Stored at ${hour(view.slot+1)}</span><strong id="projected-energy"></strong><span id="energy-loss" class="loss-note"></span></div><div><span>This hour’s cash</span><strong id="projected-cash"></strong><span class="loss-note">After throughput cost</span></div></div><button class="button primary advance" id="advance">${mode==='manual'?'Commit hour':'Play policy’s next hour'}${view.slot===5?' & see results':` & reveal ${hour(view.slot+1)}`} →</button></div>${mode!=='manual'?'<div class="baseline-actions"><button class="button ghost small" id="finish-policy">Finish this policy replay</button></div>':''}</div></section>`;}
function renderInstrument(view,p){const R=commitments(p.contracts,view.slot).reserveMW;return `<aside class="instrument" aria-label="Battery state and promises"><div class="battery-head"><h2>Energy in the battery</h2><strong>${dec(view.energyMWh)} <small>/ 8 MWh</small></strong></div><div class="battery" role="img" aria-label="${dec(view.energyMWh,2)} of 8 MWh stored${R?`, ${dec(R/MODEL.dischargeEfficiency,2)} MWh reserved this hour`:''}"><div class="battery-fill" style="width:${100*view.energyMWh/MODEL.capacityMWh}%"></div>${R?`<div class="battery-reserve" style="width:${100*R/MODEL.dischargeEfficiency/MODEL.capacityMWh}%"></div>`:''}<div class="battery-ticks" aria-hidden="true">${'<i></i>'.repeat(8)}</div></div><div class="battery-caption"><span>4 MW power limit · 8 MWh capacity</span><span>${R?`${dec(R/MODEL.dischargeEfficiency,2)} MWh reserved`:'No reserve active now'}</span></div><h3>Where your power is promised</h3><div class="legend"><span><i class="key delivery"></i>Delivery</span><span><i class="key reserve"></i>Reserve</span><span><i class="key"></i>Uncommitted</span></div>${Array.from({length:MODEL.slots},(_,t)=>{const c=commitments(p.contracts,t);const free=MODEL.powerMW-c.deliveryMW-c.reserveMW;return `<div class="power-row ${t===view.slot?'now':''} ${t<view.slot?'past':''}"><span>${hour(t)}</span><div class="power-bars" role="img" aria-label="${hour(t)}: ${c.deliveryMW} MW delivery, ${c.reserveMW} MW reserve, ${free} MW uncommitted">${c.deliveryMW?`<span class="delivery" style="width:${c.deliveryMW/4*100}%">${dec(c.deliveryMW)}</span>`:''}${c.reserveMW?`<span class="reserve" style="width:${c.reserveMW/4*100}%">${dec(c.reserveMW)}</span>`:''}<span class="free" style="width:${free/4*100}%">${free?dec(free):''}</span></div><span class="known-price">${t<view.observedPrices.length?money(view.observedPrices[t]):view.announcedPrices.some(p=>p.slot===t)?`${money(view.announcedPrices.find(p=>p.slot===t).price)}*`:'•••'}</span></div>`;}).join('')}<div class="power-scale"><span>0 MW</span><span>4 MW</span></div><p class="hint">Uncommitted power still needs enough energy to use it. ${view.done?"All prices are now observed.":view.conditions.priceNotice?"* Next hour’s price is announced; later prices stay hidden.":"Future prices stay hidden until their hour arrives."} ${selected.length?'Selected offers are included in this preview.':''}</p><div class="cash-line"><span>Cash ${view.done?'earned':'so far'}</span><strong>${money(view.cash)}</strong></div>${view.contracts.length?`<details style="margin-top:20px"><summary>${view.contracts.length} firm promise${view.contracts.length===1?'':'s'}</summary><div class="promise-list">${view.contracts.map(c=>`<div class="promise-line"><div>${esc(promiseLabel(view,c))}<br><span>${c.slot<view.slot?'fulfilled':'still binding'}</span></div><strong>${money(c.fee)}</strong></div>`).join('')}</div></details>`:''}</aside>`;}
const chartX=t=>42+t*78,chartY=e=>211-e*21;
function renderChart(view,p){
  const X=chartX,Y=chartY;const points=envelope(view,p.contracts);const before=envelope(view);
  const area=band=>band.length?`M ${band.map(q=>`${X(q.slot)},${Y(q.max)}`).join(' L ')} L ${[...band].reverse().map(q=>`${X(q.slot)},${Y(q.min)}`).join(' L ')} Z`:'';
  const history=[{slot:0,e:MODEL.initialMWh},...view.history.map(h=>({slot:h.slot+1,e:h.energyAfter}))];const path=history.map(q=>`${X(q.slot)},${Y(q.e)}`).join(' ');
  const alt=view.done?saved.filter(s=>s.id!==runId&&s.state.seed===state.seed&&s.state.conditions.priceNotice===state.conditions.priceNotice).slice(-2):[];
  const narrowed=points.map((q,i)=>({...q,old:before[i],delta:before[i].max-before[i].min-(q.max-q.min)})).sort((a,b)=>b.delta-a.delta)[0];
  const impact=view.done?'':selected.length?(narrowed?.delta>.005?`<strong>${dec(narrowed.delta,1)} MWh less range at ${hour(narrowed.slot)}.</strong> ${dec(narrowed.min)}–${dec(narrowed.max)} MWh reachable, down from ${dec(narrowed.old.min)}–${dec(narrowed.old.max)} before this selection.`:'<strong>The energy band is unchanged.</strong> The selected promise still occupies power in its delivery hour.'):'Select a promise: the old boundary will stay visible so you can see what it takes away.';
  const planned=view.done?null:projection(view,selected,dispatch);
  return `<section class="chart-panel" aria-labelledby="room-title"><div class="chart-heading"><h2 id="room-title">${view.done?'The path through the day':'Room to move'}</h2><p class="hint">${view.done?'Stored energy after each hour. Compare how each run used the same battery.':'Stored energy you can still reach while honouring every selected and firm promise.'}</p><div class="legend"><span><i class="key"></i>${view.done?'This run':'Feasible energy'}</span>${selected.length?'<span><i class="key before"></i>Before selection</span>':''}${view.done?(alt.length?'<span><i class="key previous"></i>Other runs</span>':''):'<span><i class="key planned"></i>After this hour</span>'}</div></div><svg class="energy-chart" viewBox="0 0 550 255" role="img" aria-labelledby="chart-accessible-title chart-description"><title id="chart-accessible-title">Stored energy and future feasible range</title><desc id="chart-description">Current energy ${dec(view.energyMWh,2)} MWh. ${points.slice(1).map(q=>`At ${hour(q.slot)}, reachable energy ${dec(q.min,2)} to ${dec(q.max,2)} MWh.`).join(' ')}</desc>${[0,2,4,6,8].map(e=>`<line x1="42" y1="${Y(e)}" x2="510" y2="${Y(e)}" stroke="var(--line)"/><text class="chart-y-label" x="28" y="${Y(e)+5}" text-anchor="end">${e}</text>`).join('')}<text class="chart-y-label" x="8" y="22">MWh</text>${selected.length?`<path d="${area(before)}" fill="var(--surface)" stroke="var(--line-strong)" stroke-width="1.6" stroke-dasharray="5 4"/>`:''}${area(points)?`<path d="${area(points)}" fill="var(--accent-soft)" stroke="var(--accent-line)" stroke-width="1.8"/>`:''}${alt.map(s=>`<polyline points="${[{slot:0,e:MODEL.initialMWh},...s.state.history.map(h=>({slot:h.slot+1,e:h.energyAfter}))].map(q=>`${X(q.slot)},${Y(q.e)}`).join(' ')}" fill="none" stroke="var(--line-strong)" stroke-dasharray="6 5" stroke-width="2"/>`).join('')}<polyline points="${path}" fill="none" stroke="var(--accent)" stroke-width="3" stroke-linejoin="round"/>${history.map(q=>`<circle cx="${X(q.slot)}" cy="${Y(q.e)}" r="4" fill="var(--accent)" stroke="var(--card)" stroke-width="1.5"/>`).join('')}${planned?`<line id="planned-line" x1="${X(view.slot)}" y1="${Y(view.energyMWh)}" x2="${X(view.slot+1)}" y2="${Y(planned.energyMWh)}" stroke="var(--accent)" stroke-width="2" stroke-dasharray="4 4"/><circle id="planned-stock" cx="${X(view.slot+1)}" cy="${Y(planned.energyMWh)}" r="5" fill="var(--card)" stroke="var(--accent)" stroke-width="2.5"/><line x1="${X(view.slot)}" y1="31" x2="${X(view.slot)}" y2="215" stroke="var(--accent-line)" stroke-dasharray="3 5"/>`:''}${Array.from({length:7},(_,t)=>`<text x="${X(t)}" y="240" text-anchor="middle">${hour(t)}</text>`).join('')}</svg>${impact?`<p class="selection-impact ${selected.length?'active':''}" aria-live="polite">${impact}</p>`:''}<p class="chart-foot">${view.done?'Dashed paths are other completed runs on this day with the same price notice; manual replays may be informed.':'Physical possibilities, not a forecast. More room need not mean more value.'}</p></section>`;
}
function renderFinish(view){
  const r=result(state),comparison=saved.filter(s=>s.state.seed===state.seed),gap=r.contractPriceDifference;
  return `<section class="finish-panel" aria-labelledby="finish-title"><span class="small-label">Day ${view.seed} complete · ${esc(name())} · ${informationName(view.conditions.priceNotice)}</span><h2 id="finish-title">What did your flexibility earn?</h2><div class="result-value">${money(r.value)}</div><p class="result-math">${money(r.cash)} cash ${r.stockAdjustment<0?'−':'+'} ${money(Math.abs(r.stockAdjustment))} change in stored-energy value</p><p class="result-insight">${r.accepted?`Your ${r.accepted} promises earned ${money(r.deliveryRevenue)} from energy deliveries and ${money(r.reserveRevenue)} from reserve. ${r.deliveryRevenue?`At the actual delivery-hour prices, those same contracted exports would have earned ${money(Math.abs(gap))} ${gap>=0?'less':'more'} on spot.`:''}`:'You left every future opportunity open. All physical trades settled at the price revealed in their hour.'}</p><p class="hint">${r.deliveryRevenue?'That spot comparison holds the exported MWh fixed; it is not the value of a fully different strategy. ':''}Ending stock is valued at £45 per stored MWh, with the starting stock deducted.</p>
  ${renderMatched(view.seed)}
  ${comparison.length>1?`<details class="run-history"><summary>Your completed runs on this day</summary><div class="compare-table-wrap" tabindex="0"><table class="compare-table"><thead><tr><th scope="col">Run / information</th><th scope="col">Cash</th><th scope="col">End MWh</th><th scope="col">Net value</th></tr></thead><tbody>${comparison.map(c=>{const cr=result(c.state);return `<tr class="${c.id===runId?'current':''}"><td>${esc(name(c))}<small>${informationName(c.state.conditions.priceNotice)}${c.mode==='manual'&&c.informed?' · already saw this day':''}</small></td><td>${money(cr.cash)}</td><td>${dec(cr.energyMWh)}</td><td>${money(cr.value)}</td></tr>`;}).join('')}</tbody></table></div></details>`:''}
  <details class="policy-rules"><summary>Read the two commitment rules</summary>${Object.values(POLICIES).map(p=>`<p><strong>${p.name}.</strong> ${p.description}</p>`).join('')}<p>All four matched runs start again at 12:00. One-hour notice reveals no future offers. It adds the preparation rule above; it does not optimise a day with hindsight.</p></details>
  <div class="result-actions"><button class="button" id="replay">Play this day again</button><button class="button ghost" id="export">Export this comparison</button></div><p class="compare-warning">A manual replay is informed by what you have seen. Start a new day for a fresh decision under uncertainty. These are simple rules, not optimised strategies.</p></section>`;
}
function renderLower(view){return `<div class="lower-row"><details><summary>Decision log · ${view.history.length} hours settled</summary><div class="ledger">${view.history.length?view.history.map(h=>`<div class="ledger-item"><strong>${hour(h.slot)} · ${money(h.price)}/MWh · ${money(h.cashDelta,true)}</strong><span>${h.dispatchMW<-.001?`Imported ${dec(-h.dispatchMW,2)} MWh`:h.dispatchMW>.001?`Exported ${dec(h.dispatchMW,2)} MWh`:'Held position'} → ${dec(h.energyAfter,2)} MWh stored. ${h.deliveryMW?`${dec(h.deliveryMW)} MW delivered to contracts. `:''}${h.reserveMW?`${dec(h.reserveMW)} MW held for reserve. `:''}${h.acceptedIds.length?`Accepted: ${h.acceptedIds.map(id=>esc(promiseLabel(view,view.contracts.find(c=>c.id===id)))).join('; ')}.`:''}</span></div>`).join(''):'<p class="hint">Your first decision will appear here.</p>'}</div></details><details><summary>What this little model assumes</summary><p>Fictional prices, offers and battery. Six one-hour slots; 4 MW import or export; 8 MWh storage; 4 MWh starting stock. Each hour has one net action, so charging and discharging cannot happen together.</p><p>Charging stores 90% of imported energy. Exporting 1 MWh uses 1 ÷ 0.9 MWh from storage. Each imported or exported MWh costs £2 in a simple throughput allowance. Contracts pay for their energy once; only extra exports settle at spot.</p><p>Upward reserve is a one-hour standby promise. It is never called in this model, but its MW stays unavailable for other use and its MWh stays in the battery for the full hour. This deliberately conservative rule does not model reserve activation, charge-to-discharge swing or real market products.</p><p>Accepted energy contracts force export in their hour. Feasible choices preserve a physical path to fulfil all promises, using future charging if needed. No grid limits, ramping, forecasting, self-discharge, taxes or bid optimisation are modelled.</p><p>Final stock is worth £45 per stored MWh (£50/MWh grid price × 90% discharge efficiency). This common accounting convention is not a final physical sale. Initial stock is deducted at the same rate.</p><p>Policies only receive observed prices, the announced next price when that condition is selected, current offers and existing promises. ${preparationRule} “Take firm revenue” considers simultaneous offers in their displayed order. New days use a different fixed schedule; replaying the same day preserves its schedule.</p></details></div><p class="storage-note">${storageOK?'Your current run and recent comparisons are saved in this browser.':'Browser storage is unavailable. This run works, but will not survive a reload.'} Educational model, not an operational or investment tool.</p>`;}
function render(){const view=publicView(state);const p=preview(view,selected);app.innerHTML=`<div class="day-bar"><div class="day-name"><strong>DAY ${String(view.seed).padStart(3,'0')}</strong><span>${view.done?'Settled':mode==='manual'?(informed?'Your informed replay':`Your decisions · ${informationName(view.conditions.priceNotice)}`):`Policy replay · ${POLICIES[mode].name}`}</span></div><div class="toolbar"><button class="button ghost small" id="new-day">Start new day ↗</button>${!view.done?'<button class="button ghost small" id="export">Export run</button>':''}</div></div>${renderInformation(view)}<div class="workspace">${view.done?renderFinish(view):renderDecision(view,p)}<div class="live-state">${renderChart(view,p)}${renderInstrument(view,p)}</div></div>${renderLower(view)}`;bind();bindStudy();if(!view.done)updateDispatch();}
function updateDispatch(){const view=publicView(state);const p=projection(view,selected,dispatch);const output=document.querySelector('#dispatch-output');if(!output)return;output.textContent=dispatch<-.001?`Charge ${dec(-dispatch,2)} MW`:dispatch>.001?`Export ${dec(dispatch,2)} MW`:'Hold · 0 MW';document.querySelector('#dispatch-kind').textContent=p.deliveryMW?`${dec(p.deliveryMW)} MW promised`:'One hour at this output';document.querySelector('#projected-energy').textContent=`${dec(p.energyMWh,2)} MWh`;document.querySelector('#projected-cash').textContent=money(p.cashDelta,true);const losses=dispatch<0?-dispatch*(1-MODEL.chargeEfficiency):dispatch*(1/MODEL.dischargeEfficiency-1);document.querySelector('#energy-loss').textContent=losses>.0001?`${dec(losses,2)} MWh conversion loss`:'No energy moved';document.querySelector('#planned-stock')?.setAttribute('cy',chartY(p.energyMWh));document.querySelector('#planned-line')?.setAttribute('y2',chartY(p.energyMWh));const slider=document.querySelector('#dispatch-slider');slider.value=dispatch;slider.setAttribute('aria-valuetext',output.textContent);}
function toggleOffer(id){if(mode!=='manual'||state.slot>=MODEL.slots)throw Error('Only your active run can change offers.');const next=selected.includes(id)?selected.filter(x=>x!==id):[...selected,id];const p=preview(publicView(state),next);if(!p.feasible)throw Error('That promise would make the day infeasible.');probe.liftedIds=[];selected=next;dispatch=clamp(dispatch,p.range.min,p.range.max);persist();render();document.querySelector(`[data-offer="${id}"]`)?.focus();say('Promise selection updated. The remaining feasible energy band has changed.');}
function configure({acceptedOfferIds=selected,dispatchMW}={}){if(mode!=='manual'||state.slot>=MODEL.slots)throw Error('Only your active run can stage decisions.');const view=publicView(state);const p=preview(view,acceptedOfferIds);if(!p.feasible)throw Error('Those promises cannot all be honoured.');const nextDispatch=dispatchMW===undefined?clamp(dispatch,p.range.min,p.range.max):dispatchMW;projection(view,acceptedOfferIds,nextDispatch);probe.liftedIds=[];selected=[...acceptedOfferIds];dispatch=nextDispatch;persist();render();say('Tentative decisions updated. Advance to make them firm.');}
function doAdvance(){try{state=advance(state,{acceptedIds:selected,dispatchMW:dispatch});error='';resetProbe();recordCompleted();chooseDefaults();persist();render();say(state.slot===6?'Day complete. Results and policy comparisons are ready.':`${hour(state.slot)} revealed. Spot price ${money(publicView(state).currentPrice)} per megawatt hour.`);document.querySelector(state.slot===6?'#finish-title':'#decision-title')?.setAttribute('tabindex','-1');document.querySelector(state.slot===6?'#finish-title':'#decision-title')?.focus({preventScroll:true});}catch(e){error=e.message;render();}}
function start(seed,newMode='manual',isInformed=false,priceNotice=state.conditions.priceNotice){state=createRun(seed,{priceNotice});resetProbe();mode=newMode;informed=isInformed;runId=`${Date.now()}-${Math.random().toString(16).slice(2,7)}`;error='';chooseDefaults();persist();render();window.scrollTo({top:0,behavior:'instant'});say(`Day ${seed} started. ${name()}.`);}
function exportReport(){const view=publicView(state);const matches=saved.filter(s=>s.state.seed===state.seed);const r=result(state);const rows=view.history.map(h=>`| ${hour(h.slot)} | ${money(h.price)} | ${dec(h.dispatchMW,2)} | ${dec(h.energyAfter,2)} | ${money(h.cashDelta)} | ${h.acceptedIds.map(id=>state.contracts.find(c=>c.id===id)).map(c=>`${c.kind} ${c.mw} MW at ${hour(c.slot)}`).join('; ')||'—'} |`).join('\n');downloadText(`flexibility-day-${state.seed}.md`,`# Where flexibility gets trapped — day ${state.seed}\n\n${name()} · ${informationName(state.conditions.priceNotice)} · ${view.done?'Complete':`${view.slot} of 6 hours settled`}\n\nCash: ${money(r.cash)}. Stored energy: ${dec(r.energyMWh,2)} MWh. ${view.done?`Net value including terminal stock adjustment: ${money(r.value)}.`:''}\n\n| Hour | Spot / MWh | Net output MW | Ending stock MWh | Cash | New promises |\n| --- | ---: | ---: | ---: | ---: | --- |\n${rows}\n\n${matches.length?`## Completed runs on this same day\n\n| Run | Cash | End MWh | Net value |\n| --- | ---: | ---: | ---: |\n${matches.map(s=>{const x=result(s.state);return `| ${name(s)} · ${informationName(s.state.conditions.priceNotice)} | ${money(x.cash)} | ${dec(x.energyMWh,2)} | ${money(x.value)} |`;}).join('\n')}\n\n`:''}${view.done?comparisonMarkdown():inspectorOpen?probeMarkdown():''}Fictional educational model. 4 MW / 8 MWh battery; 4 MWh initial stock; 90% efficiency in each direction; £2/MWh throughput allowance. One-hour upward reserve is never called but holds both power and stored energy. Terminal stock valued at £45/stored MWh, less initial stock at the same value. Policies see only their declared current or one-hour-ahead prices and current offers. ${preparationRule} Manual replays are informed by prior runs. No claim of market realism or optimality.\n`,'text/markdown;charset=utf-8');say('Run exported as Markdown.');}
function bind(){document.querySelector('#new-day')?.addEventListener('click',()=>start(state.seed>=999999?1:state.seed+1));document.querySelector('#export')?.addEventListener('click',exportReport);document.querySelectorAll('[data-offer]').forEach(b=>b.addEventListener('click',()=>toggleOffer(b.dataset.offer)));document.querySelector('#dispatch-slider')?.addEventListener('input',e=>{dispatch=Number(e.target.value);persist();updateDispatch();});document.querySelectorAll('[data-dispatch]').forEach(b=>b.addEventListener('click',()=>{const r=preview(publicView(state),selected).range;dispatch=b.dataset.dispatch==='charge'?r.min:b.dataset.dispatch==='export'?r.max:clamp(0,r.min,r.max);persist();updateDispatch();say(document.querySelector('#dispatch-output').textContent);}));document.querySelector('#advance')?.addEventListener('click',doAdvance);document.querySelectorAll('[data-policy]').forEach(b=>b.addEventListener('click',()=>start(state.seed,b.dataset.policy,false,Number(b.dataset.notice))));document.querySelector('#replay')?.addEventListener('click',()=>start(state.seed,'manual',true));document.querySelector('#finish-policy')?.addEventListener('click',()=>{while(state.slot<MODEL.slots){state=advance(state,policyDecision(publicView(state),mode));}recordCompleted();chooseDefaults();persist();render();say('Policy replay complete. The comparison is ready.');});}
function bindProbeResults(){
  document.querySelectorAll('[data-lift]').forEach(input=>input.addEventListener('change',()=>{
    probe.liftedIds=input.checked?[...probe.liftedIds,input.dataset.lift]:probe.liftedIds.filter(id=>id!==input.dataset.lift);
    updateProbe();document.querySelector(`[data-lift="${input.dataset.lift}"]`)?.focus({preventScroll:true});
  }));
  document.querySelectorAll('[data-release]').forEach(button=>button.addEventListener('click',()=>{
    const d=diagnose(publicView(state),selected,probe),set=d.releaseSets[Number(button.dataset.release)];
    probe.liftedIds=[...probe.liftedIds,...set];updateProbe();
    document.querySelector(`[data-lift="${set[0]}"]`)?.focus({preventScroll:true});say('Hypothetical releases applied. Your real promises and cash are unchanged.');
  }));
}
function updateProbe(){
  document.querySelector('#probe-results').innerHTML=renderProbeResults(publicView(state),selected,probe);
  const output=document.querySelector('#probe-output-value'),slider=document.querySelector('#probe-output');
  if(output)output.textContent=outputName(probe.dispatchMW);
  slider?.setAttribute('aria-valuetext',outputName(probe.dispatchMW));bindProbeResults();
}
function bindStudy(){
  document.querySelector('#price-notice')?.addEventListener('change',event=>{
    const notice=Number(event.target.value);informed=informed||state.conditions.priceNotice>notice;state={...state,conditions:{priceNotice:notice}};if(mode!=='manual')chooseDefaults();persist();render();
    document.querySelector('#price-notice')?.focus({preventScroll:true});
  });
  document.querySelector('#option-inspector')?.addEventListener('toggle',event=>{inspectorOpen=event.target.open;});
  document.querySelectorAll('[data-inspect-offer]').forEach(button=>button.addEventListener('click',()=>{
    probe={kind:'offer',offerId:button.dataset.inspectOffer,dispatchMW:3,liftedIds:[]};inspectorOpen=true;render();
    document.querySelector('#probe-kind')?.focus();
  }));
  document.querySelector('#probe-kind')?.addEventListener('change',event=>{
    const value=event.target.value;probe={kind:value==='dispatch'?'dispatch':'offer',offerId:value==='dispatch'?null:value,dispatchMW:probe.dispatchMW,liftedIds:[]};inspectorOpen=true;render();
    document.querySelector('#probe-kind')?.focus({preventScroll:true});
  });
  document.querySelector('#probe-output')?.addEventListener('input',event=>{probe.dispatchMW=Number(event.target.value);updateProbe();});
  bindProbeResults();
}
function comparisonMarkdown(){return `## Matched policies × information\n\nSame day, battery, offers, settlement and current-price thresholds.\n\n| Policy | Price notice | Cash | End MWh | Net value |\n| --- | --- | ---: | ---: | ---: |\n${matchedComparison(state.seed).map(r=>`| ${POLICIES[r.policy].name} | ${informationName(r.priceNotice)} | ${money(r.result.cash)} | ${dec(r.result.energyMWh,2)} | ${money(r.result.value)} |`).join('\n')}\n\n${preparationRule}\n\n`;}
function probeMarkdown(){const v=publicView(state),d=diagnose(v,selected,probe);return `## Hypothetical option at ${hour(v.slot)}\n\n${probe.kind==='dispatch'?outputName(probe.dispatchMW):promiseLabel(v,d.candidate)}. ${d.allowed?'Feasible.':'Blocked.'} ${d.reasons.join(' ')}\n\nHypothetically lifted: ${d.removable.filter(c=>probe.liftedIds.includes(c.id)).map(c=>promiseLabel(v,c)).join('; ')||'none'}. Stock and time held fixed; past cash and energy effects are not rewound. Current tentative offers: ${selected.join(', ')||'none'}.\n\n`;}
// Small public surface for accessibility tooling or an optional host WebMCP wrapper.
// This intentionally returns only the same current information visible in the UI.
window.flexibilityExperiment={getState:()=>({view:publicView(state),mode,selected:[...selected],dispatchMW:dispatch,feasible:preview(publicView(state),selected).range}),configure,chooseOffer:toggleOffer,setDispatch:(mw)=>{if(state.slot>=MODEL.slots)throw Error('This day is complete.');if(mode!=='manual')throw Error('Policy replay actions are fixed.');projection(publicView(state),selected,mw);dispatch=mw;persist();updateDispatch();return {dispatchMW:dispatch};},advance:()=>{if(state.slot>=MODEL.slots)throw Error('This day is complete.');doAdvance();return publicView(state);}};
persist();render();
let unregisterTools=registerFlexibilityTools(window.flexibilityExperiment);
window.addEventListener('pagehide',()=>unregisterTools());
window.addEventListener('pageshow',event=>{if(event.persisted)unregisterTools=registerFlexibilityTools(window.flexibilityExperiment);});
